/// Parses a postfix operator, if there is one and its precedence is at
/// least min_precedence.
fn parse_postfix_operator_at(
    &mut self,
    min_precedence: Precedence,
) -> Result<Option<PostfixOperator>> {
    let token = self.peek()?;
    let op = match token {
        Some(Token::Exclamation) => {
            self.next()?;
            PostfixOperator::Factorial
        }
        Some(Token::Keyword(Keyword::Is)) => {
            self.next()?;
            let not = self.next_is(Token::Keyword(Keyword::Not));
            let literal = match self.next()? {
                Token::Keyword(Keyword::Null) => ast::Literal::Null,
                Token::Keyword(Keyword::NaN) => ast::Literal::Float(f64::NAN),
                t => return errinput!("expected NULL or NaN after IS, got {t}"),
            };
            if not {
                PostfixOperator::IsNot(literal)
            } else {
                PostfixOperator::Is(literal)
            }
        }
        _ => return Ok(None),
    };

    if op.precedence() >= min_precedence {
        Ok(Some(op))
    } else {
        Ok(None)
    }
}

